from sympy.logic.boolalg import And, Or, Not, BooleanTrue, BooleanFalse

xs = symbols("x0:10")
TRUE, FALSE = BooleanTrue(), BooleanFalse()

def decode(checkpoint):
    w0 = W[f"{checkpoint}.w0"]
    layers = [(w0, W[f"{checkpoint}.b0"])]
    for i in range(1, 4):
        layers.append((W[f"{checkpoint}.w{i}"], W[f"{checkpoint}.b{i}"]))

    @lru_cache(None)
    def at_least(terms, k):
        if k <= 0:
            return TRUE
        if k > len(terms):
            return FALSE
        if not terms:
            return FALSE
        return Or(at_least(terms[1:], k), And(terms[0], at_least(terms[1:], k - 1)))

    def affine_ge(channels, coeffs, bias, threshold):
        terms = []
        constant = int(round(float(bias)))
        for channel, coeff in zip(channels, coeffs):
            coeff = int(round(float(coeff)))
            if coeff > 0:
                terms.extend(level for level in channel for _ in range(coeff))
            elif coeff < 0:
                for level in channel:
                    constant += coeff
                    terms.extend(Not(level) for _ in range(-coeff))
        return at_least(tuple(terms), int(threshold) - constant)

    # Each channel is represented by its nested threshold indicators [h>=1, h>=2, ...].
    h = [(x,) for x in xs]
    maxima = [1] * 10

    for matrix, bias in layers:
        next_h, next_maxima = [], []
        for row in range(34):
            coeffs = [float(matrix[row, col]) for col in range(len(h))]
            b = int(round(float(bias[row])))
            upper = max(0, b + sum(int(round(c)) * maxima[j]
                                   for j, c in enumerate(coeffs) if c > 0))
            next_maxima.append(upper)
            next_h.append(tuple(affine_ge(h, coeffs, b, k) for k in range(1, upper + 1)))
        h, maxima = next_h, next_maxima

    out = W[f"{checkpoint}.out"]
    bias = W[f"{checkpoint}.bias"]

    # Class 1 wins iff its score is strictly above class 0 and at least class 2.
    c10 = [float(out[1, j] - out[0, j]) for j in range(34)]
    c12 = [float(out[1, j] - out[2, j]) for j in range(34)]
    above0 = affine_ge(h, c10, float(bias[1] - bias[0]), 1)
    above2 = affine_ge(h, c12, float(bias[1] - bias[2]), 0)
    return And(above0, above2)

def output_bits(expr):
    bits = []
    for values in product((False, True), repeat=10):
        result = expr.subs(dict(zip(xs, values)))
        bits.append("1" if result == TRUE else "0")
    return "".join(bits)

