def inp(i):
    return {"op": "input", "index": i}

def unary(op, arg):
    return {"op": op, "arg": arg}

def binary(op, left, right):
    return {"op": op, "left": left, "right": right}

a = binary(
    "xor",
    binary("xnor", inp(6), inp(7)),
    binary("or", inp(7), inp(9)),
)
b = unary(
    "not",
    binary(
        "and",
        binary("xor", inp(0), inp(4)),
        binary("nand", inp(3), inp(8)),
    ),
)
before = binary("and", unary("not", inp(6)), binary("or", a, b))
after = binary("and", inp(0), unary("not", inp(0)))

