def repair_xnor(node):
    if isinstance(node, list):
        return [repair_xnor(x) for x in node]
    if not isinstance(node, dict):
        return node
    node = {k: repair_xnor(v) for k, v in node.items()}
    if node.get("op") == "xnor":
        left, right = node["left"], node["right"]
        return {"op": "not", "arg": {"op": "xor", "left": left, "right": right}}
    return node

